/*
**    date_trunc( UNIT, TIMESTRING )
**
** Truncate the timestring to the specified precision.
** UNIT can be: 'year', 'month', 'day', 'hour', 'minute', 'second'
** Returns a string in the format 'YYYY-MM-DD HH:MM:SS'
*/
static void dateTruncFunc(
  sqlite3_context *context,
  int argc,
  sqlite3_value **argv
){
  DateTime x;
  const char *zUnit;
  int Y, M, D, h, m, s;
  char zBuf[32];

  /* Validate argument count */
  if( argc != 2 ){
    sqlite3_result_error(context, "date_trunc() requires 2 arguments", -1);
    return;
  }

  /* Extract and validate precision argument */
  zUnit = (const char *)sqlite3_value_text(argv[0]);
  if( zUnit == 0 ){
    sqlite3_result_null(context);
    return;
  }

  /* Normalize unit to lowercase for comparison */
  char unit[16];
  int i;
  for(i = 0; i < 15 && zUnit[i]; i++){
    unsigned char c = (unsigned char)zUnit[i];
    unit[i] = (char)(c >= 'A' && c <= 'Z' ? c + 32 : c);
  }
  unit[i] = '\0';

  /* Parse the datetime value */
  if( isDate(context, argc-1, argv+1, &x) ){
    return;
  }

  /* Extract components */
  computeYMD_HMS(&x);
  Y = x.Y;
  M = x.M;
  D = x.D;
  h = x.h;
  m = x.m;
  s = (int)x.s;

  /* Truncate based on unit */
  if( sqlite3StrICmp(unit, "year")==0 ){
    M = 1;
    D = 1;
    h = 0;
    m = 0;
    s = 0;
  }else if( sqlite3StrICmp(unit, "month")==0 ){
    D = 1;
    h = 0;
    m = 0;
    s = 0;
  }else if( sqlite3StrICmp(unit, "day")==0 ){
    h = 0;
    m = 0;
    s = 0;
  }else if( sqlite3StrICmp(unit, "hour")==0 ){
    m = 0;
    s = 0;
  }else if( sqlite3StrICmp(unit, "minute")==0 ){
    s = 0;
  }
  /* For "second", keep all components as is */

  /* Format the result */
  if( Y < 0 ){
    zBuf[0] = '-';
    Y = -Y;
  }
  zBuf[1] = '0' + (Y/1000)%10;
  zBuf[2] = '0' + (Y/100)%10;
  zBuf[3] = '0' + (Y/10)%10;
  zBuf[4] = '0' + (Y)%10;
  zBuf[5] = '-';
  zBuf[6] = '0' + (M/10)%10;
  zBuf[7] = '0' + (M)%10;
  zBuf[8] = '-';
  zBuf[9] = '0' + (D/10)%10;
  zBuf[10] = '0' + (D)%10;
  zBuf[11] = ' ';
  zBuf[12] = '0' + (h/10)%10;
  zBuf[13] = '0' + (h)%10;
  zBuf[14] = ':';
  zBuf[15] = '0' + (m/10)%10;
  zBuf[16] = '0' + (m)%10;
  zBuf[17] = ':';
  zBuf[18] = '0' + (s/10)%10;
  zBuf[19] = '0' + (s)%10;
  zBuf[20] = 0;

  if( Y < 0 ){
    sqlite3_result_text(context, zBuf, 19, SQLITE_TRANSIENT);
  }else{
    sqlite3_result_text(context, &zBuf[1], 19, SQLITE_TRANSIENT);
  }
}


